namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage2; class hidove extends cloudStorage2 { var $host = ''; var $apitype; public function init() { $this->host = $this->options->cloud_storage_hidove_host; $this->token = $this->options->cloud_storage_hidove_token; $this->apitype = $this->options->cloud_storage_hidove_apitype; $this->silent_scanning = $this->options->cloud_storage_hidove_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_hidove_delete_attachment_after_synced; } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; $target_url = $this->host . '/api/upload'; if (function_exists('curl_file_create')) { $file = curl_file_create($source_path); } else { $file = '@' . realpath($source_path); } $post = array( 'image' => $file, 'apiType' => $this->apitype, 'token' => $this->token ); $headers = array('Content-Type: multipart/form-data'); $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $target_url); curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false); curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, false); curl_setopt($ch, CURLOPT_POST, true); curl_setopt($ch, CURLOPT_POSTFIELDS, $post); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_HTTPHEADER, $headers); $result = curl_exec($ch); curl_close($ch); $result = json_decode($result, true);; if ($result['code'] == 200) { do_action( 'qqworld-collector-log', $this->log_id, 'Hidove Pro:', print_r($result, true) ); $url = $result['data']['url'][$this->apitype]; if (preg_match('/^http/i', $url)) return $url; else do_action( 'qqworld-collector-log', $this->log_id, 'Hidove Pro failed: ', print_r($result, true) ); } else { do_action( 'qqworld-collector-log', $this->log_id, 'Hidove Pro failed: ', print_r($result, true) ); } return false; } public function add_could_storage_form($guid) { $this->accessed = $this->is_current; require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } } ?>